package com.reinforcedchesthighlighter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** A short, transparent full-canvas flash when the chest's teleport trap activates. */
public class ChestTrapAlertOverlay extends Overlay
{
    private final Client client;
    private final ReinforcedChestPlugin plugin;
    private final ReinforcedChestConfig config;

    @Inject
    public ChestTrapAlertOverlay(Client client, ReinforcedChestPlugin plugin, ReinforcedChestConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        int alpha = plugin.getTrapFlashAlpha();
        if (alpha <= 0)
        {
            return null;
        }

        Color configured = config.trapFlashColor();
        if (configured == null)
        {
            return null;
        }
        graphics.setColor(new Color(configured.getRed(), configured.getGreen(), configured.getBlue(), alpha));
        graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
        return null;
    }
}

package com.reinforcedchesthighlighter;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("reinforcedchesthighlighter")
public interface ReinforcedChestConfig extends Config
{
    @ConfigSection(
        name = "Chest",
        description = "Chest highlight settings",
        position = 0
    )
    String chestSection = "chest";

    @ConfigSection(
        name = "TP Alarm",
        description = "Alerts for the chest teleport trap",
        position = 1,
        closedByDefault = true
    )
    String trapAlarmSection = "trapAlarm";

    enum HighlightStyle
    {
        HULL_OUTLINE,
        FILLED_HULL,
        TILE,
        MODEL_OUTLINE
    }

    @ConfigItem(
        position = 1,
        keyName = "highlightIdle",
        name = "Show idle chest",
        description = "Highlight the chest before it's opened.",
        section = chestSection
    )
    default boolean highlightIdle()
    {
        return true;
    }

    @Alpha
    @ConfigItem(
        position = 2,
        keyName = "idleColor",
        name = "Idle colour",
        description = "Highlight colour for the idle chest.",
        section = chestSection
    )
    default Color idleColor()
    {
        return Color.GREEN;
    }

    @ConfigItem(
        position = 3,
        keyName = "highlightOpened",
        name = "Show opened chest",
        description = "Highlight the chest after it's been opened.",
        section = chestSection
    )
    default boolean highlightOpened()
    {
        return true;
    }

    @Alpha
    @ConfigItem(
        position = 4,
        keyName = "openedColor",
        name = "Opened colour",
        description = "Highlight colour for the opened chest.",
        section = chestSection
    )
    default Color openedColor()
    {
        return Color.RED;
    }

    @ConfigItem(
        position = 5,
        keyName = "highlightStyle",
        name = "Highlight style",
        description = "Choose how the chest is highlighted.",
        section = chestSection
    )
    default HighlightStyle highlightStyle()
    {
        return HighlightStyle.HULL_OUTLINE;
    }

    @Range(min = 1, max = 8)
    @ConfigItem(
        position = 6,
        keyName = "borderWidth",
        name = "Line width",
        description = "Outline thickness in pixels.",
        section = chestSection
    )
    default int borderWidth()
    {
        return 2;
    }

    @Range(min = 0, max = 255)
    @ConfigItem(
        position = 7,
        keyName = "fillOpacity",
        name = "Fill opacity",
        description = "Opacity used with the Filled Hull style.",
        section = chestSection
    )
    default int fillOpacity()
    {
        return 45;
    }

    @ConfigItem(
        position = 10,
        keyName = "trapFlashEnabled",
        name = "Screen flash",
        description = "Flash the screen when the chest trap activates.",
        section = trapAlarmSection
    )
    default boolean trapFlashEnabled()
    {
        return true;
    }

    @ConfigItem(
        position = 11,
        keyName = "trapFlashColor",
        name = "Flash colour",
        description = "Colour of the screen flash.",
        section = trapAlarmSection
    )
    default Color trapFlashColor()
    {
        return Color.RED;
    }

    @Range(min = 0, max = 180)
    @ConfigItem(
        position = 12,
        keyName = "trapFlashOpacity",
        name = "Flash strength",
        description = "How strong the screen flash appears.",
        section = trapAlarmSection
    )
    default int trapFlashOpacity()
    {
        return 55;
    }

    @Range(min = 1, max = 10)
    @ConfigItem(
        position = 13,
        keyName = "trapFlashSeconds",
        name = "Flash duration",
        description = "How long the flash lasts, in seconds.",
        section = trapAlarmSection
    )
    default int trapFlashSeconds()
    {
        return 3;
    }

    @Range(min = 350, max = 1200)
    @ConfigItem(
        position = 14,
        keyName = "trapFlashIntervalMs",
        name = "Flash interval (ms)",
        description = "Time between on/off changes; higher is slower.",
        section = trapAlarmSection
    )
    default int trapFlashIntervalMs()
    {
        return 600;
    }

    @ConfigItem(
        position = 15,
        keyName = "trapSoundEnabled",
        name = "Play sound",
        description = "Play a sound when the chest trap activates.",
        section = trapAlarmSection
    )
    default boolean trapSoundEnabled()
    {
        return true;
    }

    @Range(min = 1, max = 65535)
    @ConfigItem(
        position = 16,
        keyName = "trapSoundId",
        name = "Sound ID",
        description = "RuneScape sound effect ID. Default: 3813.",
        section = trapAlarmSection
    )
    default int trapSoundId()
    {
        return 3813;
    }

    @Range(min = 0, max = 127)
    @ConfigItem(
        position = 17,
        keyName = "trapSoundVolume",
        name = "Sound volume",
        description = "Alert volume, from 0 to 127.",
        section = trapAlarmSection
    )
    default int trapSoundVolume()
    {
        return 64;
    }
}

package com.reinforcedchesthighlighter;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class ReinforcedChestOverlay extends Overlay
{
    private final Client client;
    private final ReinforcedChestPlugin plugin;
    private final ReinforcedChestConfig config;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    public ReinforcedChestOverlay(Client client, ReinforcedChestPlugin plugin,
        ReinforcedChestConfig config, ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null)
        {
            return null;
        }

        ReinforcedChestConfig.HighlightStyle style = config.highlightStyle();
        int width = Math.max(1, Math.min(8, config.borderWidth()));

        for (GameObject chest : plugin.getChests())
        {
            if (chest.getWorldView() != worldView || chest.getPlane() != worldView.getPlane())
            {
                continue;
            }

            Color colour = plugin.getColour(chest);
            if (colour == null)
            {
                continue;
            }

            if (style == ReinforcedChestConfig.HighlightStyle.MODEL_OUTLINE)
            {
                modelOutlineRenderer.drawOutline(chest, width, colour, 0);
                continue;
            }

            Shape shape = style == ReinforcedChestConfig.HighlightStyle.TILE
                ? chest.getCanvasTilePoly()
                : chest.getConvexHull();
            if (shape == null)
            {
                shape = chest.getCanvasTilePoly();
            }
            if (shape == null)
            {
                continue;
            }

            int alpha = style == ReinforcedChestConfig.HighlightStyle.FILLED_HULL
                ? Math.max(0, Math.min(255, config.fillOpacity()))
                : 0;
            Color fill = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha);
            OverlayUtil.renderPolygon(graphics, shape, colour, fill, new BasicStroke(width));
        }
        return null;
    }
}

package com.reinforcedchesthighlighter;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Reinforced Chest Highlighter",
    description = "Highlight a reinforced chest according to its current object ID",
    tags = {"chest", "sailing", "object", "highlight"}
)
public class ReinforcedChestPlugin extends Plugin
{
    // Fixed IDs: kept in code so the RuneLite settings have no ID entry boxes.
    private static final int IDLE_CHEST_ID = 60517;
    private static final int OPENED_CHEST_ID = 60519;
    // OSRS game message reported for the reinforced chest's teleport trap.
    private static final String TRAP_MESSAGE = "you have activated a trap on the chest.";
    private static final long ALERT_DEBOUNCE_NANOS = 1_000_000_000L;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private OverlayManager overlayManager;
    @Inject private ReinforcedChestOverlay overlay;
    @Inject private ChestTrapAlertOverlay trapAlertOverlay;
    @Inject private ReinforcedChestConfig config;

    // Identity-based tracking avoids treating two different objects on one tile as equal.
    private final Set<GameObject> chests = Collections.newSetFromMap(new IdentityHashMap<>());
    private volatile long lastTrapAlertNanos = 0;

    @Provides
    ReinforcedChestConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(ReinforcedChestConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        overlayManager.add(trapAlertOverlay);
        // Also finds chests already nearby when the plugin is enabled.
        clientThread.invoke(this::scanCurrentScene);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlayManager.remove(trapAlertOverlay);
        lastTrapAlertNanos = 0;
        chests.clear();
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        trackIfRelevant(event.getGameObject());
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        chests.remove(event.getGameObject());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOADING ||
            event.getGameState() == GameState.LOGIN_SCREEN ||
            event.getGameState() == GameState.HOPPING)
        {
            chests.clear();
            // Preserve a live alert through LOADING during an island teleport.
            // Logging out or hopping cancels the alert.
            if (event.getGameState() != GameState.LOADING)
            {
                lastTrapAlertNanos = 0;
            }
        }
        else if (event.getGameState() == GameState.LOGGED_IN)
        {
            scanCurrentScene();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        // Only messages originating from the game, never public or private player chat.
        if (client.getGameState() != GameState.LOGGED_IN ||
            (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM))
        {
            return;
        }

        String message = event.getMessage();
        if (message == null || !Text.standardize(message).contains(TRAP_MESSAGE))
        {
            return;
        }

        // Prevent duplicate game-message events from playing multiple sounds.
        long now = System.nanoTime();
        if (lastTrapAlertNanos != 0 && now - lastTrapAlertNanos < ALERT_DEBOUNCE_NANOS)
        {
            return;
        }
        lastTrapAlertNanos = now;

        if (config.trapSoundEnabled() && config.trapSoundVolume() > 0)
        {
            client.playSoundEffect(config.trapSoundId(), config.trapSoundVolume());
        }
    }

    // Called from the overlay renderer. The flash is based on elapsed time,
    // so it will end even if game ticks temporarily stop during a teleport.
    int getTrapFlashAlpha()
    {
        if (!config.trapFlashEnabled() || lastTrapAlertNanos == 0)
        {
            return 0;
        }

        long elapsed = System.nanoTime() - lastTrapAlertNanos;
        long duration = Math.max(1, Math.min(10, config.trapFlashSeconds())) * 1_000_000_000L;
        if (elapsed < 0 || elapsed >= duration)
        {
            return 0;
        }

        long interval = Math.max(350, Math.min(1200, config.trapFlashIntervalMs())) * 1_000_000L;
        return (elapsed / interval) % 2 == 0
            ? Math.max(0, Math.min(180, config.trapFlashOpacity()))
            : 0;
    }

    Set<GameObject> getChests()
    {
        return chests;
    }

    // Resolve impostors each time we draw: a chest can change appearance/ID
    // when a varbit changes without producing an object-spawn event.
    Color getColour(GameObject object)
    {
        int id = object.getId();
        ObjectComposition definition = client.getObjectDefinition(id);
        if (definition != null && definition.getImpostorIds() != null)
        {
            ObjectComposition current = definition.getImpostor();
            if (current == null)
            {
                return null;
            }
            id = current.getId();
        }

        if (id == OPENED_CHEST_ID)
        {
            return config.highlightOpened() ? config.openedColor() : null;
        }
        if (id == IDLE_CHEST_ID)
        {
            return config.highlightIdle() ? config.idleColor() : null;
        }
        return null;
    }

    private void trackIfRelevant(GameObject object)
    {
        if (object == null)
        {
            return;
        }

        int id = object.getId();
        if (id == IDLE_CHEST_ID || id == OPENED_CHEST_ID)
        {
            chests.add(object);
            return;
        }

        // Some scenery has a stable base ID but switches visible IDs (impostors).
        ObjectComposition definition = client.getObjectDefinition(id);
        if (definition != null && definition.getImpostorIds() != null)
        {
            for (int candidateId : definition.getImpostorIds())
            {
                if (candidateId == IDLE_CHEST_ID || candidateId == OPENED_CHEST_ID)
                {
                    chests.add(object);
                    return;
                }
            }
        }
    }

    private void scanCurrentScene()
    {
        chests.clear();
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null || worldView.getScene() == null)
        {
            return;
        }

        Tile[][][] tiles = worldView.getScene().getTiles();
        if (tiles == null)
        {
            return;
        }

        for (Tile[][] plane : tiles)
        {
            for (Tile[] column : plane)
            {
                for (Tile tile : column)
                {
                    if (tile != null && tile.getGameObjects() != null)
                    {
                        for (GameObject object : tile.getGameObjects())
                        {
                            trackIfRelevant(object);
                        }
                    }
                }
            }
        }
    }
}
